def _decode(raw: str) -> pd.DataFrame:
    text = base64.b64decode(raw.replace('\\n', '')).decode('utf-8')
    rows = json.loads(text)
    return pd.DataFrame(
        [[r[1], r[2], r[3], r[4]] for r in rows],
        columns=['Open', 'High', 'Low', 'Close'],
        index=pd.to_datetime([r[0] for r in rows], utc=True),
    )


def test_real_scoped_history_entry_parity_snapshot():
    cases = [
        ('EURUSD', EURUSD_B64, 'CTRADER:DEMO:47810571', 249),
        ('XAUUSD', XAUUSD_B64, 'CTRADER:DEMO:47810571', 236),
    ]
    reports = {}
    for symbol, fixture, scope, expected_count in cases:
        frame = _decode(fixture)
        assert len(frame) == expected_count
        report = compare_v3b_entry_decisions(symbol, frame, account_scope=scope)
        reports[symbol] = report
        assert report['mismatches'] == [], report
        assert report['match'] is True
    assert sum(report['compared_setups'] for report in reports.values()) > 0
